Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using vi = vector<int>;
using db = double;
#define pb push_back
#define fir first
#define sec second

int n, k, mod;
int f[250006][27];

#define lbit(i) ((i)&-(i))

const int N = 250001;
int fac[N], inv[N], ifac[N];

int main() {

	cin >> n >> k >> mod;

	inv[1] = fac[0] = fac[1] = ifac[0] = ifac[1] = 1;
	for (int i = 2; i < N; ++i) {
		inv[i] = (ll)mod / i * (mod - inv[mod % i]) % mod;
		fac[i] = (ll)fac[i - 1] * i % mod;
		ifac[i] = (ll)ifac[i - 1] * inv[i] % mod;
	}

	ll ans = 1;
	for (int i = 1; i <= n; ++i)
		(ans *= k) %= mod;

	if (n % 2 == 0) {
		f[0][0] = 1;
		for (int i = 1; i <= n; ++i) if ((n & i) == i) // 要从小到大枚举子集
			for (int msk = i - lbit(i), j = msk; ; --j &= msk) {
				int len = min(k - 1, __builtin_popcount(j));
				for (int t = 0; t <= len; ++t)
					f[i][t + 1] = (f[i][t + 1] + (ll)f[j][t] * ifac[i - j]) % mod;
				if (!j) break;
			}
		for (int i = 1; i <= k; ++i)
			(ans -= (ll)f[n][i] * fac[n] % mod * fac[k] % mod * ifac[k - i]) %= mod;
	}

	cout << (ans + mod) % mod << endl;

	return 0;
}

</original_code>
